-- =========================================================================
-- POSTGRESQL MIGRATION: GENERAL INTELLIGENCE AND REASONING
-- Questions: 990
-- =========================================================================
-- =========================================================================
-- 1. EXTENSIONS & SCHEMAS
-- =========================================================================
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- =========================================================================
-- 2. DEDICATED MASTER TABLE: public.rrb_ntpc_graduate_pyqs
-- =========================================================================
CREATE TABLE IF NOT EXISTS public.rrb_ntpc_graduate_pyqs (
    id VARCHAR(60) PRIMARY KEY,
    master_id INTEGER NOT NULL UNIQUE,
    subject VARCHAR(100) NOT NULL,
    chapter_id VARCHAR(50) NOT NULL,
    chapter_num INTEGER NOT NULL,
    chapter_name VARCHAR(150) NOT NULL,
    chapter_q_num INTEGER NOT NULL,
    subtopic TEXT,
    exam_name VARCHAR(50) DEFAULT 'RRB NTPC',
    exam_tag VARCHAR(150),
    exam_stage VARCHAR(50),
    exam_date VARCHAR(50),
    exam_shift VARCHAR(50),
    target_level VARCHAR(50) DEFAULT 'Graduate',
    question_text TEXT NOT NULL,
    question_text_hi TEXT,
    options JSONB NOT NULL,
    options_hi JSONB,
    correct_option VARCHAR(10) NOT NULL,
    solution_text TEXT,
    solution_text_hi TEXT,
    has_image BOOLEAN DEFAULT FALSE,
    image_type VARCHAR(50),
    svg_content TEXT,
    option_svgs JSONB,
    solution_svg TEXT,
    verification_status VARCHAR(50) DEFAULT 'verified',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for lightning-fast querying and chapter filtering
CREATE INDEX IF NOT EXISTS idx_ntpc_pyq_subject ON public.rrb_ntpc_graduate_pyqs(subject);
CREATE INDEX IF NOT EXISTS idx_ntpc_pyq_chapter ON public.rrb_ntpc_graduate_pyqs(chapter_id);
CREATE INDEX IF NOT EXISTS idx_ntpc_pyq_has_image ON public.rrb_ntpc_graduate_pyqs(has_image);
CREATE INDEX IF NOT EXISTS idx_ntpc_pyq_exam_tag ON public.rrb_ntpc_graduate_pyqs(exam_tag);

-- Enable RLS and public read policies
ALTER TABLE public.rrb_ntpc_graduate_pyqs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow anon read on rrb_ntpc_graduate_pyqs" ON public.rrb_ntpc_graduate_pyqs;
CREATE POLICY "Allow anon read on rrb_ntpc_graduate_pyqs" ON public.rrb_ntpc_graduate_pyqs FOR SELECT TO anon, authenticated USING (true);

-- =========================================================================
-- 3. PLATFORM COMPATIBILITY: public.questions Table
-- =========================================================================
CREATE TABLE IF NOT EXISTS public.questions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    test_id VARCHAR(100) NOT NULL,
    question_number INTEGER NOT NULL,
    part_number INTEGER,
    section_name VARCHAR(100),
    section_title VARCHAR(100),
    chapter_name VARCHAR(150),
    difficulty VARCHAR(50),
    question_text TEXT NOT NULL,
    question_text_hi TEXT,
    options JSONB NOT NULL,
    options_hi JSONB,
    correct_option VARCHAR(10) NOT NULL,
    solution_text TEXT,
    solution_text_hi TEXT,
    image_svg TEXT,
    image_svg_hi TEXT,
    option_svgs JSONB,
    CONSTRAINT unique_test_question UNIQUE (test_id, question_number)
);

ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow anon read on questions" ON public.questions;
CREATE POLICY "Allow anon read on questions" ON public.questions FOR SELECT TO anon, authenticated USING (true);

-- =========================================================================
-- 4. CANDIDATE RESPONSES & PRACTICE TRACKING TABLE
-- =========================================================================
CREATE TABLE IF NOT EXISTS public."RRB_NTPC_PYQ_responses" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name_of_candidate VARCHAR(100) NOT NULL DEFAULT 'Candidate',
    candidate_mobile VARCHAR(15) NOT NULL,
    question_id VARCHAR(60) NOT NULL,
    subject VARCHAR(100) NOT NULL,
    chapter_id VARCHAR(50) NOT NULL,
    chapter_name VARCHAR(150) NOT NULL,
    correct_answer VARCHAR(10) NOT NULL,
    his_answer VARCHAR(10),
    time_taken_seconds INTEGER DEFAULT 0,
    is_correct BOOLEAN GENERATED ALWAYS AS (correct_answer = his_answer) STORED,
    attempt_number INTEGER DEFAULT 1,
    submitted_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT unique_pyq_candidate_question UNIQUE (candidate_mobile, question_id)
);

ALTER TABLE public."RRB_NTPC_PYQ_responses" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow anon all on RRB_NTPC_PYQ_responses" ON public."RRB_NTPC_PYQ_responses";
CREATE POLICY "Allow anon all on RRB_NTPC_PYQ_responses" ON public."RRB_NTPC_PYQ_responses" FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

-- =========================================================================
-- 5. TEST CATALOG REGISTRATION (Discovery in mock_tests / tests)
