) VALUES (
  'RRB_NTPC_REASON_CH01_Q0020', 2305, 'General Intelligence and Reasoning', 'reason_ch01', 1, 'Analogy', 20,
  'Number Set Analogy (Square and Offset)', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 19/03/2026 (12:45 PM - 2:15 PM)', 'Stage-I / Stage-II', '19/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'Select the set in which the numbers are related in the same way as are the numbers of the following sets.
(NOTE : Operations should be performed on the whole numbers, without breaking down the numbers into
their constituent digits. E.g. 13 - Operations on 13 such as adding / subtracting / multiplying etc. to 13 can be
