INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH01_Q0024', 2309, 'General Intelligence and Reasoning', 'reason_ch01', 1, 'Analogy', 24,
  'Number Pair Analogy (Linear Transformation)', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 24/03/2026 (4:30 PM - 6:00 PM)', 'Stage-I / Stage-II', '24/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  '6 is related to 80 following a certain logic. Following the same logic, 12 is related to 140. To which of the
following is 24 related, following the same logic?
(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into
their constituent digits. E.g. 13 - Operations on 13 such as adding/ subtracting /multiplying to 13 can be
performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not
allowed.)', NULL, '{"a": "280", "b": "270", "c": "260", "d": "290"}'::jsonb, NULL, 'c',
  'Pattern: Second number = (First number × 10) + 20.
- For 6: 6 × 10 + 20 = 60 + 20 = 80.
- For 12: 12 × 10 + 20 = 120 + 20 = 140.
Following the same logic for 24:
- 24 × 10 + 20 = 240 + 20 = 260.
Hence, option (C) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
