INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH01_Q0036', 2321, 'General Intelligence and Reasoning', 'reason_ch01', 1, 'Analogy', 36,
  'Proportional Analogy (Direct Proportion)', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 25/03/2026 (9:00 AM - 10:30 AM)', 'Stage-I / Stage-II', '25/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'What number will be in the place of x?
2.8 : 3.8 : : x : 5.7', NULL, '{"a": "4.8", "b": "3.6", "c": "5.1", "d": "4.2"}'::jsonb, NULL, 'd',
  'Given proportion: 2.8 : 3.8 : : x : 5.7.
By property of proportions (Product of Extremes = Product of Means):
2.8 × 5.7 = 3.8 × x
=> x = (2.8 × 5.7) / 3.8
Notice that 5.7 / 3.8 simplifies by dividing numerator and denominator by 1.9 to 3 / 2 = 1.5.
=> x = 2.8 × 1.5 = 4.2.
Hence, option (D) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
