INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH01_Q0075', 2360, 'General Intelligence and Reasoning', 'reason_ch01', 1, 'Analogy', 75,
  'Number Pair Analogy (Linear Transformation)', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 22/03/2026 (12:45 PM - 2:15 PM)', 'Stage-I / Stage-II', '22/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  '8 is related to 41 following a certain logic. Following the same logic, 81 is related to 406. To which of the
following is 13 related, following the same logic?
(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into
their constituent digits. E.g. 13 - Operations on 13 such as adding/subtracting/multiplying etc. to 13, can be
performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not
allowed.)', NULL, '{"a": "64", "b": "66", "c": "68", "d": "62"}'::jsonb, NULL, 'b',
  'Pattern: Second number = (First number × 5) + 1.
- For 8: 8 × 5 + 1 = 40 + 1 = 41.
- For 81: 81 × 5 + 1 = 405 + 1 = 406.
Following the same logic for 13:
- 13 × 5 + 1 = 65 + 1 = 66.
Hence, option (B) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
