  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH01_Q0079', 2364, 'General Intelligence and Reasoning', 'reason_ch01', 1, 'Analogy', 79,
  'Letter Triad Analogy (Position Permutation)', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 19/03/2026 (9:00 AM - 10:30 AM)', 'Stage-I / Stage-II', '19/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'Select the triad which follows the same pattern as that followed by the two pairs given below. Both pairs
follow the same pattern.
CLUB-CUBL-ULCB
HANG-HNGA-NAHG', NULL, '{"a": "MASK-MSKA-SAMK", "b": "EARN-ARNE-ENRA", "c": "NEST-ETNS-TNSE", "d": "BALD-DLAB-LADB"}'::jsonb, NULL, 'a',
  'Pattern of letter positions (1-2-3-4):
- Word 1: 1-2-3-4 (CLUB)
- Word 2: 1-3-4-2 (CUBL)
- Word 3: 3-2-1-4 (ULCB)
Verification on Set 2:
- Word 1: 1-2-3-4 (HANG)
- Word 2: 1-3-4-2 (HNGA)
- Word 3: 3-2-1-4 (NAHG)
Applying this to options:
- Option (A): MASK (1-2-3-4) -> MSKA (1-3-4-2) -> SAMK (3-2-1-4).
Hence, option (A) follows the exact same letter transformation.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
