INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH02_Q0001', 2368, 'General Intelligence and Reasoning', 'reason_ch02', 2, 'Blood Relation', 1,
  'Family Tree Generation and Traversal', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 17/03/2026 (12:45 PM - 2:15 PM)', 'Stage-I / Stage-II', '17/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'In a certain code language,
A + B means ''A is the mother of B''
A - B means ''A is the brother of B''
A x B means ''A is the wife of B''
A % B means ''A is the father of B''
A # B means ''A is the daughter of B''
Based on the above, how is T related to G if ''G # N # V + K # T''?', NULL, '{"a": "Sister''s daughter", "b": "Mother''s father", "c": "Daughter''s daughter", "d": "Mother''s sister"}'::jsonb, NULL, 'b',
  'Given code definitions:
- A + B means ''A is the mother of B''
- A - B means ''A is the brother of B''
- A x B means ''A is the wife of B''
- A % B means ''A is the father of B''
- A # B means ''A is the daughter of B''
Expression: G # N # V + K # T
Decoding step-by-step:
1. G # N -> G is the daughter of N.
2. N # V -> N is the daughter of V.
3. V + K -> V is the mother of K.
4. K # T -> K is the daughter of T. Since V is already the mother of K, T must be the husband of V (and father of K and N).
Since N is the daughter of V and T, T is the father of N.
Since G is the daughter of N, T is G''s mother''s father.
Hence, option (B) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
