INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2377, 2, 'reason_ch02', 'General Intelligence and Reasoning', 'Blood Relation', 'Graduate',
  'In a certain code language,
A + B means ''A is the daughter of B''
A - B means ''A is the brother of B''
A x B means ''A is the wife of B''
A ÷ B means ''A is the father of B''
Based on the above, how is D related to J if ''D + F - G x H ÷ J''?', NULL, '{"a": "Mothers brothers wife", "b": "Mothers brothers daughter", "c": "Fathers brothers daughter", "d": "Fathers brothers wife"}'::jsonb, NULL, 'b', 'Given code definitions:
- A + B means ''A is the daughter of B''
- A - B means ''A is the brother of B''
- A x B means ''A is the wife of B''
- A ÷ B means ''A is the father of B''
Expression: D + F - G x H ÷ J
Decoding step-by-step:
1. D + F -> D is the daughter of F.
2. F - G -> F is the brother of G.
3. G x H -> G is the wife of H.
4. H ÷ J -> H is the father of J (and G is the mother of J).
Since G is the mother of J, and F is the brother of G, F is J''s mother''s brother.
Since D is the daughter of F, D is J''s mother''s brother''s daughter.
Hence, option (B) is the correct answer.', NULL,
  NULL, NULL, NULL
)
