INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2382, 2, 'reason_ch02', 'General Intelligence and Reasoning', 'Blood Relation', 'Graduate',
  'In a certain code language,
A + B means ''A is the mother of B''
A - B means ''A is the brother of B''
A x B means ''A is the wife of B''
A % B means ''A is the father of B''
A # B means ''A is the daughter of B''
Based on the above, how is L related to E if ''L # N - C # V x E''?', NULL, '{"a": "Son''s daughter", "b": "Daughter''s son", "c": "Brother''s daughter", "d": "Father''s mother"}'::jsonb, NULL, 'a', 'Given code definitions:
- A + B means ''A is the mother of B''
- A - B means ''A is the brother of B''
- A x B means ''A is the wife of B''
- A % B means ''A is the father of B''
- A # B means ''A is the daughter of B''
Expression: L # N - C # V x E
Decoding step-by-step:
1. L # N -> L is the daughter of N.
2. N - C -> N is the brother of C (N is male).
3. C # V -> C is the daughter of V.
4. V x E -> V is the wife of E (E is husband/father of C and N).
From (2), (3), and (4): N is the son of E and V.
Since L is the daughter of N, L is E''s son''s daughter.
Hence, option (A) is the correct answer.', NULL,
  NULL, NULL, NULL
)
