) VALUES (
  'RRB_NTPC_REASON_CH02_Q0042', 2409, 'General Intelligence and Reasoning', 'reason_ch02', 2, 'Blood Relation', 42,
  'Grandparent-Grandchild Relationship', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 17/03/2026 (9:00 AM - 10:30 AM)', 'Stage-I / Stage-II', '17/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
