INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH02_Q0044', 2411, 'General Intelligence and Reasoning', 'reason_ch02', 2, 'Blood Relation', 44,
  'Linear Coded Relations', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 25/03/2026 (12:45 PM - 2:15 PM)', 'Stage-I / Stage-II', '25/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'In a certain code language,
A + B means ''A is the husband of B''
A - B means ''A is the daughter of B''
A × B means ''A is the brother of B''
A ÷ B means ''A is the sister of B''
Based on the above, how is S related to M if ''S × R - U + N ÷ M''?', NULL, '{"a": "Daughter''s son", "b": "Brother''s son", "c": "Sisters son", "d": "Son''s son"}'::jsonb, NULL, 'c',
  'Given code definitions:
- A + B means ''A is the husband of B''
- A - B means ''A is the daughter of B''
- A × B means ''A is the brother of B''
- A ÷ B means ''A is the sister of B''
Expression: S × R - U + N ÷ M
Decoding step-by-step:
1. S × R -> S is the brother of R (S is male).
2. R - U -> R is the daughter of U.
3. U + N -> U is the husband of N (N is the wife).
4. N ÷ M -> N is the sister of M.
From (1), (2), and (3): U and N are parents of S and R. S is the son of N.
Since N is the sister of M, S is M''s sister''s son (nephew).
Hence, option (C) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
