INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH02_Q0047', 2414, 'General Intelligence and Reasoning', 'reason_ch02', 2, 'Blood Relation', 47,
  'Grandparent-Grandchild Relationship', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 24/03/2026 (9:00 AM - 10:30 AM)', 'Stage-I / Stage-II', '24/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'In a certain code language,
A + B means ''A is the wife of B''
A - B means ''A is the mother of B''
A × B means ''A is the father of B''
A ÷ B means ''A is the husband of B''
Based on the above, how is Y related to S if ''Y + N × K ÷ T - S''?', NULL, '{"a": "Father''s sister", "b": "Mother", "c": "Father''s mother", "d": "Sister"}'::jsonb, NULL, 'c',
  'Given code definitions:
- A + B means ''A is the wife of B''
- A - B means ''A is the mother of B''
- A × B means ''A is the father of B''
- A ÷ B means ''A is the husband of B''
Expression: Y + N × K ÷ T - S
Decoding step-by-step:
1. Y + N -> Y is the wife of N.
2. N × K -> N is the father of K (so Y is the mother of K).
3. K ÷ T -> K is the husband of T.
4. T - S -> T is the mother of S (so K is the father of S).
Since K is the father of S, and Y is the mother of K, Y is S''s father''s mother (paternal grandmother).
Hence, option (C) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
