INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH04_Q0058', 2538, 'General Intelligence and Reasoning', 'reason_ch04', 4, 'Coding-Decoding', 58,
  'Alternating Signed Shift Series', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 24/03/2026 (4:30 PM - 6:00 PM)', 'Stage-I / Stage-II', '24/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'WXPL is related to VZMP in a certain way based on the English alphabetical order. In the same way, ZUQH is
related to YWNL. To which of the following is TRKF related, following the same logic?', NULL, '{"a": "RTFL", "b": "STHJ", "c": "UPNB", "d": "SUGK"}'::jsonb, NULL, 'b',
  'Analyze the letter transformations in the reference pairs:
1. ''WXPL'' to ''VZMP'':
- W(23) - 1 = V(22)
- X(24) + 2 = Z(26)
- P(16) - 3 = M(13)
- L(12) + 4 = P(16)
Pattern: [-1, +2, -3, +4].

2. ''ZUQH'' to ''YWNL'':
- Z(26) - 1 = Y(25)
- U(21) + 2 = W(23)
- Q(17) - 3 = N(14)
- H(8) + 4 = L(12)
Pattern: [-1, +2, -3, +4].

3. Applying to ''TRKF'':
- T(20) - 1 = S(19)
- R(18) + 2 = T(20)
- K(11) - 3 = H(8)
- F(6) + 4 = J(10)
Result = STHJ.
Hence, option (B) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
