  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH04_Q0059', 2539, 'General Intelligence and Reasoning', 'reason_ch04', 4, 'Coding-Decoding', 59,
  'Set Intersection / Unique Digit Identification', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 17/03/2026 (9:00 AM - 10:30 AM)', 'Stage-I / Stage-II', '17/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'In a certain code language, ''WAND'' is coded as ''1846'' and ''GNAW'' is coded as ''4165''. What is the code for
''G'' in that language?
2089', NULL, '{"a": "6", "b": "5", "c": "1", "d": "4"}'::jsonb, NULL, 'b',
  'Given:
- ''WAND'' is coded as ''1846''
- ''GNAW'' is coded as ''4165''

Comparing both words:
- Common letters in ''WAND'' and ''GNAW'': {W, A, N}
- Common digits in ''1846'' and ''4165'': {1, 4, 6}

The letter ''G'' is present in ''GNAW'' but not in ''WAND''.
The digit present in ''4165'' but not in ''1846'' is ''5''.
Thus, the code for ''G'' is 5.
Hence, option (B) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
