) VALUES (
  'RRB_NTPC_REASON_CH05_Q0018', 2612, 'General Intelligence and Reasoning', 'reason_ch05', 5, 'Data Sufficiency', 18,
  'Linear Ordering Sufficiency', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 22/03/2026 (9:00 AM - 10:30 AM)', 'Stage-I / Stage-II', '22/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'In this question, a question is followed by two statements numbered (I) and (II). You have to decide whether
