) VALUES (
  'RRB_NTPC_REASON_CH05_Q0022', 2616, 'General Intelligence and Reasoning', 'reason_ch05', 5, 'Data Sufficiency', 22,
  'Linear Ordering Sufficiency', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 22/03/2026 (4:30 PM - 6:00 PM)', 'Stage-I / Stage-II', '22/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'In this question, a question is followed by two statements numbered (I) and (II). You have to decide whether
