INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH07_Q0001', 2644, 'General Intelligence and Reasoning', 'reason_ch07', 7, 'Mathematical Operations', 1,
  'BODMAS Evaluation', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 16/03/2026 (4:30 PM - 6:00 PM)', 'Stage-I / Stage-II', '16/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'If ''A'' stands for ''÷'', ''B'' stands for ''×'', ''C'' stands for ''+'' and ''D'' stands for ''-'', then what will come in place of
the question mark (?) in the following equation?
9 B 4 C 6 D 45 A 5 = ?', NULL, '{"a": "34", "b": "32", "c": "31", "d": "33"}'::jsonb, NULL, 'd',
  'Given operator definitions:
- A stands for ÷
- B stands for ×
- C stands for +
- D stands for −

Given equation: 9 B 4 C 6 D 45 A 5 = ?
Substitute operators:
= 9 × 4 + 6 − 45 ÷ 5

Apply BODMAS / PEMDAS rule step-by-step:
1. Division: 45 ÷ 5 = 9
 Expression becomes: 9 × 4 + 6 − 9
2. Multiplication: 9 × 4 = 36
 Expression becomes: 36 + 6 − 9
3. Addition: 36 + 6 = 42
4. Subtraction: 42 − 9 = 33

Thus, the result is 33.
Hence, option (D) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
