INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH09_Q0001', 2709, 'General Intelligence and Reasoning', 'reason_ch09', 9, 'Number Series / Missing Number', 1,
  'Subtractive Prime Gaps', 'RRB NTPC', 'RRB NTPC Graduate Level (2025/2026) - 27/03/2026 (12:45 PM - 2:15 PM)', 'Stage-I / Stage-II', '27/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'What should come in place of ''?'' in the given series?
82 80 77 72 65 ?', NULL, '{"a": "56", "b": "53", "c": "54", "d": "55"}'::jsonb, NULL, 'c',
  'Analyze the difference between consecutive numbers in the series:
- 82 − 80 = 2
- 80 − 77 = 3
- 77 − 72 = 5
- 72 − 65 = 7
Notice that the subtractions are consecutive prime numbers: 2, 3, 5, 7.
The next prime number after 7 is 11.
Therefore, the missing number is: 65 − 11 = 54.
Hence, option (C) is the correct answer.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
