    <rect x="130" y="20" width="80" height="105" rx="6" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>
    <text x="170" y="45" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#0369a1">Fig II</text>
    <text x="170" y="80" text-anchor="middle" font-family="sans-serif" font-size="16" font-weight="bold" fill="#075985">Row 2</text>

    <rect x="230" y="20" width="80" height="105" rx="6" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>
    <text x="270" y="45" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#b45309">Fig III</text>
