INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH10_Q0007', 2821, 'General Intelligence and Reasoning', 'reason_ch10', 10, 'Puzzle Test', 7,
  'Day / Scheduling Puzzle', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '25/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'Each of F, G, H, I, M, N and O has an exam on a different day of a week starting from Monday and ending on Sunday of the same week. Only three people have exams between I and O. O has exam on the last day of the week. Only one person has exam between F and H. N has exam immediately the day before M. G doesn''t have exam on Friday. How many people have exam(s) between G and N?', NULL, '{"a": "Four", "b": "Three", "c": "Two", "d": "One"}'::jsonb, NULL, 'b',
  'Step-by-step deduction:
1. Days: Monday(1), Tuesday(2), Wednesday(3), Thursday(4), Friday(5), Saturday(6), Sunday(7).
2. ''O has exam on the last day of the week'' -> Sunday = O.
3. ''Only three people have exams between I and O'' -> Between Wednesday and Sunday are 3 days (Thu, Fri, Sat). Thus, Wednesday = I.
4. ''N has exam immediately the day before M'' -> N and M occupy consecutive days (N followed by M).
5. ''G doesn''t have exam on Friday'' and ''Only one person has exam between F and H''.
6. If N and M are on Friday and Saturday: remaining days are Mon, Tue, Thu. Gap between Tue and Thu is 1 day (Wednesday), allowing F and H on Tuesday and Thursday! Then Monday = G.
7. Schedule: Mon = G, Tue = F/H, Wed = I, Thu = H/F, Fri = N, Sat = M, Sun = O.
8. Number of people between G (Monday) and N (Friday) = 3 people (Tuesday, Wednesday, Thursday).
Hence, the correct option is B (Three).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
ON CONFLICT (id) DO UPDATE SET
