INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2821, 10, 'reason_ch10', 'General Intelligence and Reasoning', 'Puzzle Test', 'Graduate',
  'Each of F, G, H, I, M, N and O has an exam on a different day of a week starting from Monday and ending on Sunday of the same week. Only three people have exams between I and O. O has exam on the last day of the week. Only one person has exam between F and H. N has exam immediately the day before M. G doesn''t have exam on Friday. How many people have exam(s) between G and N?', NULL, '{"a": "Four", "b": "Three", "c": "Two", "d": "One"}'::jsonb, NULL, 'b', 'Step-by-step deduction:
1. Days: Monday(1), Tuesday(2), Wednesday(3), Thursday(4), Friday(5), Saturday(6), Sunday(7).
2. ''O has exam on the last day of the week'' -> Sunday = O.
3. ''Only three people have exams between I and O'' -> Between Wednesday and Sunday are 3 days (Thu, Fri, Sat). Thus, Wednesday = I.
4. ''N has exam immediately the day before M'' -> N and M occupy consecutive days (N followed by M).
5. ''G doesn''t have exam on Friday'' and ''Only one person has exam between F and H''.
6. If N and M are on Friday and Saturday: remaining days are Mon, Tue, Thu. Gap between Tue and Thu is 1 day (Wednesday), allowing F and H on Tuesday and Thursday! Then Monday = G.
7. Schedule: Mon = G, Tue = F/H, Wed = I, Thu = H/F, Fri = N, Sat = M, Sun = O.
8. Number of people between G (Monday) and N (Friday) = 3 people (Tuesday, Wednesday, Thursday).
Hence, the correct option is B (Three).', NULL,
  NULL, NULL, NULL
)
