INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2826, 10, 'reason_ch10', 'General Intelligence and Reasoning', 'Puzzle Test', 'Graduate',
  'Each of A, B, L, I, N, G and S has exam on a different day of a week starting from Monday and ending on Sunday of the same week. B has exam on first day of the week. Only three people have exam between B and L. Only one person has exam between L and A. N has exam on Sunday. S has exam on one of the days after I but on one of the days before G. Who has exam on Thursday?', NULL, '{"a": "G", "b": "I", "c": "A", "d": "S"}'::jsonb, NULL, 'd', 'Step-by-step deduction:
1. Days: Mon(1), Tue(2), Wed(3), Thu(4), Fri(5), Sat(6), Sun(7).
2. ''B has exam on first day of the week'' -> Monday = B.
3. ''Only three people have exam between B and L'' -> 3 people between Mon and Friday. Thus, Friday = L.
4. ''Only one person has exam between L and A'' -> A can be Wednesday (between Wed and Fri is Thu = 1 day).
5. ''N has exam on Sunday'' -> Sunday = N.
6. ''S has exam on one of the days after I but on one of the days before G'' -> I < S < G.
7. Available days are Tuesday(2), Thursday(4), Saturday(6). With I < S < G: Tuesday = I, Thursday = S, Saturday = G.
8. Who has exam on Thursday? S.
Hence, the correct option is D (S).', NULL,
  NULL, NULL, NULL
)
