INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2836, 10, 'reason_ch10', 'General Intelligence and Reasoning', 'Puzzle Test', 'Graduate',
  'Each of P, Q, R, S, T, U and V has an exam on a different day of a week starting from Monday and ending on Sunday of the same week. Only five people have exams between V and T. Only two people have exams between R and T. Q has the exam immediately after R. S has the exam immediately before P but after T. How many people have exams between P and U?', NULL, '{"a": "One", "b": "Two", "c": "Three", "d": "Four"}'::jsonb, NULL, 'b', 'Step-by-step deduction:
1. Days: Mon(1), Tue(2), Wed(3), Thu(4), Fri(5), Sat(6), Sun(7).
2. ''Only five people have exams between V and T'' -> V and T are on Monday and Sunday (days 1 and 7).
3. ''S has the exam immediately before P but after T'' -> T must be Monday(1), so V is Sunday(7)! And S, P are after T.
4. ''Only two people have exams between R and T'' -> T is Monday(1), so Thursday(4) = R (Tue and Wed between).
5. ''Q has the exam immediately after R'' -> Friday(5) = Q.
6. ''S has the exam immediately before P'' -> S and P must occupy Tuesday(2) and Wednesday(3).
7. The remaining day is Saturday(6) = U.
8. Complete schedule: Mon = T, Tue = S, Wed = P, Thu = R, Fri = Q, Sat = U, Sun = V.
9. Number of people between P (Wednesday) and U (Saturday) = Thursday and Friday = 2 people (R and Q).
Hence, the correct option is B (Two).', NULL,
  NULL, NULL, NULL
)
