INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH10_Q0037', 2851, 'General Intelligence and Reasoning', 'reason_ch10', 10, 'Puzzle Test', 37,
  'Box Stacking Puzzle', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '17/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'Seven boxes, A, B, C, D, E, F and G, are kept one over the other but not necessarily in the same order. Only two boxes are kept between D and B. Only E is kept above G. No box is kept below B. A is kept at some place below C but at some place above F. How many boxes are kept between B and G?', NULL, '{"a": "2", "b": "1", "c": "3", "d": "4"}'::jsonb, NULL, 'd',
  'Step-by-step deduction:
1. 7 boxes: positions 1 at bottom to 7 at top.
2. ''No box is kept below B'' -> B is at position 1.
3. ''Only E is kept above G'' -> G is at position 6, and E is at position 7.
4. ''Only two boxes are kept between D and B'' -> Between B(1) and D are 2 boxes (2 and 3), so D is at position 4.
5. ''A is kept at some place below C but at some place above F'' -> C > A > F.
 Available positions are 5, 3, 2. Thus C = 5, A = 3, F = 2.
6. Stack from top (7) to bottom (1): E, G, C, D, A, F, B.
7. Number of boxes between B (position 1) and G (position 6) = positions 2, 3, 4, 5 (F, A, D, C) = 4 boxes.
Hence, the correct option is D (4).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
