INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH10_Q0064', 2878, 'General Intelligence and Reasoning', 'reason_ch10', 10, 'Puzzle Test', 64,
  'Box Stacking Puzzle', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '18/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'Seven boxes, A, B, C, D, E, F and G, are kept one over the other but not necessarily in the same order. F is kept second from the bottom. Only three boxes are kept between F and D. G is kept at one of the positions below F. Only E is kept between D and B. A is kept at one of the positions above D. How many boxes are kept above C?', NULL, '{"a": "4", "b": "2", "c": "3", "d": "1"}'::jsonb, NULL, 'a',
  'Step-by-step deduction:
1. 7 boxes: positions 1 at bottom to 7 at top.
2. ''F is kept second from the bottom'' -> F is at position 2.
3. ''G is kept at one of the positions below F'' -> G is at position 1.
4. ''Only three boxes are kept between F and D'' -> D is at position 6 (positions 3, 4, 5 between).
5. ''A is kept at one of the positions above D'' -> A is at position 7.
6. ''Only E is kept between D and B'' -> Between D(6) and B there is only E, so E is at position 5 and B is at position 4.
7. The remaining position 3 is occupied by C.
8. Stack from top (7) to bottom (1): A, D, E, B, C, F, G.
9. Number of boxes kept above C (position 3) = positions 4, 5, 6, 7 (B, E, D, A) = 4 boxes.
Hence, the correct option is A (4).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
