) VALUES (
  'RRB_NTPC_REASON_CH10_Q0068', 2882, 'General Intelligence and Reasoning', 'reason_ch10', 10, 'Puzzle Test', 68,
  'Floor Puzzle', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '22/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'A, B, C, D, E and F live on six different floors of the same building. The lowermost floor in the building is numbered 1, the floor above it is numbered 2 and so on till the topmost floor, which is numbered 6. Only one person lives above D. Only two people live between A and D. F lives immediately above B. E does not live above D. How many people live below C?', NULL, '{"a": "Five", "b": "Three", "c": "Four", "d": "Two"}'::jsonb, NULL, 'a',
  'Step-by-step deduction:
1. 6 floors: 1 to 6.
2. ''Only one person lives above D'' -> Floor 5 = D.
