INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2882, 10, 'reason_ch10', 'General Intelligence and Reasoning', 'Puzzle Test', 'Graduate',
  'A, B, C, D, E and F live on six different floors of the same building. The lowermost floor in the building is numbered 1, the floor above it is numbered 2 and so on till the topmost floor, which is numbered 6. Only one person lives above D. Only two people live between A and D. F lives immediately above B. E does not live above D. How many people live below C?', NULL, '{"a": "Five", "b": "Three", "c": "Four", "d": "Two"}'::jsonb, NULL, 'a', 'Step-by-step deduction:
1. 6 floors: 1 to 6.
2. ''Only one person lives above D'' -> Floor 5 = D.
3. ''Only two people live between A and D'' -> Floor 2 = A (floors 3 and 4 between).
4. ''F lives immediately above B'' -> F and B are consecutive (F = B + 1). Available floors: 1, 3, 4, 6. Consecutive floors are 4 and 3, so Floor 4 = F, Floor 3 = B.
5. Available floors: 1 and 6 for C and E. ''E does not live above D'' (E != 6), so Floor 1 = E, Floor 6 = C.
6. Floor arrangement: Floor 6 = C, Floor 5 = D, Floor 4 = F, Floor 3 = B, Floor 2 = A, Floor 1 = E.
7. Number of people living below C (Floor 6) = Floors 1 to 5 = 5 people (E, A, B, F, D).
Hence, the correct option is A (Five).', NULL,
  NULL, NULL, NULL
)
