INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH11_Q0010', 2892, 'General Intelligence and Reasoning', 'reason_ch11', 11, 'Seating Arrangement', 10,
  'Linear Seating Arrangement', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '24/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'Seven people, B, C, O, P, Q, R and S, are sitting in a straight line, facing north. Only four people sit to the right of S. B sits immediately to the left of P. Only three people sit between P and C, none of whom sit on the extreme ends. R sits immediately to the right of Q. How many people sit between O and R?', NULL, '{"a": "Zero", "b": "Two", "c": "One", "d": "Three"}'::jsonb, NULL, 'c',
  'Step-by-step deduction:
1. 7 people in straight line facing north (positions 1 to 7 left to right).
2. ''Only four people sit to the right of S'' -> Position 3 = S.
3. ''B sits immediately to the left of P'' (B, P adjacent).
4. ''Only three people sit between P and C, none of whom sit on the extreme ends'' -> P and C occupy positions 2 and 6 (between them are 3, 4, 5 = 3 people). Since B is immediately left of P, B = 1, P = 2, and C = 6.
5. ''R sits immediately to the right of Q'' -> Q and R occupy positions 4 and 5 (Q = 4, R = 5).
6. The remaining position is Position 7 = O.
7. Line arrangement: 1:B, 2:P, 3:S, 4:Q, 5:R, 6:C, 7:O.
8. Number of people between O (7) and R (5) = Position 6 = 1 person (C).
Hence, the correct option is C (One).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
