INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH11_Q0050', 2932, 'General Intelligence and Reasoning', 'reason_ch11', 11, 'Seating Arrangement', 50,
  'Floor Puzzle', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '25/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'C, D, N, O, P and Q live on six different floors of the same building. The lowermost floor in the building is numbered 1, the floor above it is numbered 2 and so on, till the topmost floor, which is numbered 6. No one lives above D. Only two people live between D and C. Only two people live between O and Q. Q lives below C but above N. How many people live between P and N?', NULL, '{"a": "One", "b": "Three", "c": "Zero", "d": "Two"}'::jsonb, NULL, 'd',
  'Step-by-step deduction:
1. 6 floors: 1 to 6.
2. ''No one lives above D'' -> Floor 6 = D.
3. ''Only two people live between D and C'' -> Floor 3 = C (floors 4 and 5 between).
4. ''Q lives below C but above N'' -> Floor 2 = Q, Floor 1 = N.
5. ''Only two people live between O and Q'' -> Floor 5 = O (floors 3 and 4 between).
6. The remaining floor is Floor 4 = P.
7. Floor arrangement: Floor 6 = D, Floor 5 = O, Floor 4 = P, Floor 3 = C, Floor 2 = Q, Floor 1 = N.
8. Number of people living between P (Floor 4) and N (Floor 1) = Floors 2 and 3 = 2 people (Q and C).
Hence, the correct option is D (Two).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
