INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2937, 12, 'reason_ch12', 'General Intelligence and Reasoning', 'Syllogism', 'Graduate',
  'Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusion(s) logically follow(s) from the statements. Statements: All pigs are jackals. All pigs are cats. All elephants are cats. Conclusions: (I) All elephants are jackals. (II) Some cats are jackals.', NULL, '{"a": "Only conclusion (I) follows.", "b": "Neither conclusion (I) nor (II) follows.", "c": "Both conclusions (I) and (II) follow.", "d": "Only conclusion (II) follows."}'::jsonb, NULL, 'd', 'Step-by-step syllogism analysis:
Statements: All pigs are jackals. All pigs are cats. All elephants are cats.
- Pig is a subset of both Jackal and Cat.
- Since the set Pig is non-empty and contained in both Cat and Jackal, Cat and Jackal must intersect at least at Pig.
Conclusions:
(I) All elephants are jackals: False, no relation is given between elephants and jackals.
(II) Some cats are jackals: True, the cats that are pigs are also jackals.
Only conclusion (II) follows.
Hence, the correct option is D.', NULL,
  NULL, NULL, NULL
)
