INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH12_Q0007', 2939, 'General Intelligence and Reasoning', 'reason_ch12', 12, 'Syllogism', 7,
  'Syllogism - Statements & Conclusions', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '24/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'Read the given statements and conclusions carefully. You have to take the given statements to be true even if they seem to be at variance from commonly known facts. You have to decide which conclusion/s logically follow/s from the given statements. Statements: All carrots are peas. All peas are onions. No pea is a tomato. Conclusions: (I) No onion is a tomato. (II) No carrot is a tomato.', NULL, '{"a": "Only conclusion II follows.", "b": "Neither conclusion I nor II follows.", "c": "Only conclusion I follows.", "d": "Both conclusions I and II follow."}'::jsonb, NULL, 'a',
  'Step-by-step syllogism analysis:
Statements: All carrots are peas. All peas are onions. No pea is a tomato.
- Carrot is a subset of Pea, which is a subset of Onion.
- Pea and Tomato are completely disjoint.
Conclusions:
(I) No onion is a tomato: False, onions outside peas can be tomatoes.
(II) No carrot is a tomato: True, because all carrots are inside peas, and no pea is tomato.
Only conclusion II follows.
Hence, the correct option is A.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
