INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH12_Q0014', 2946, 'General Intelligence and Reasoning', 'reason_ch12', 12, 'Syllogism', 14,
  'Syllogism - Statements & Conclusions', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '17/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusion(s) logically follow(s) from the statements. Statements: All sand is stone. All sand is cement. Some cements are mud. Conclusions: (I) Some muds are sand. (II) Some cements are stone.', NULL, '{"a": "Only conclusion (II) follows.", "b": "Neither conclusion (I) nor (II) follows.", "c": "Only conclusion (I) follows.", "d": "Both conclusions (I) and (II) follow."}'::jsonb, NULL, 'a',
  'Step-by-step syllogism analysis:
Statements: All sand is stone. All sand is cement. Some cements are mud.
- Sand is inside both Stone and Cement.
- Therefore, Cement and Stone must share at least the subset Sand, so Some cements are stone.
Conclusions:
(I) Some muds are sand: False, mud only overlaps cement, not necessarily sand.
(II) Some cements are stone: True.
Only conclusion (II) follows.
Hence, the correct option is A.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
