INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH12_Q0044', 2976, 'General Intelligence and Reasoning', 'reason_ch12', 12, 'Syllogism', 44,
  'Syllogism - Statements & Conclusions', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '17/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements. Statements: Some ants are lizards. All lizards are spiders. No spider is a rat. Conclusions: (I) Some rats are lizards. (II) Some spiders are ants.520', NULL, '{"a": "Only conclusion (II) follows", "b": "Neither conclusion (I) nor (II) follows", "c": "Both conclusions (I) and (II) follow", "d": "Only conclusion (I) follows"}'::jsonb, NULL, 'a',
  'Step-by-step syllogism analysis:
Statements: Some ants are lizards. All lizards are spiders. No spider is a rat.
- Lizards are a subset of Spiders. Since Some ants are lizards, those ants are also spiders, meaning Some spiders are ants (Conclusion II follows).
- Spiders and Rats are completely disjoint. Since lizards are inside spiders, no lizard can be a rat (Conclusion I is false).
Only conclusion (II) follows.
Hence, the correct option is A.', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
