INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2978, 12, 'reason_ch12', 'General Intelligence and Reasoning', 'Syllogism', 'Graduate',
  'Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements. Statements: All bananas are apples. All apples are grapes. Some grapes are oranges. Conclusions: (I) All grapes are bananas. (II) All oranges are apples.523', NULL, '{"a": "Only conclusion (I) follows", "b": "Only conclusion (II) follows", "c": "Both conclusions (I) and (II) follow", "d": "Neither conclusion (I) nor (II) follows"}'::jsonb, NULL, 'd', 'Step-by-step syllogism analysis:
Statements: All bananas are apples. All apples are grapes. Some grapes are oranges.
- Banana is inside Apple, inside Grape. Grape is a superset of Banana, so ''All grapes are bananas'' does not follow.
- Oranges overlap Grapes, but not necessarily Apples, so ''All oranges are apples'' does not follow.
Neither conclusion (I) nor (II) follows.
Hence, the correct option is D.', NULL,
  NULL, NULL, NULL
)
