INSERT INTO public.questions (
  test_id, question_number, part_number, section_name, section_title, chapter_name, difficulty,
  question_text, question_text_hi, options, options_hi, correct_option, solution_text, solution_text_hi,
  image_svg, image_svg_hi, option_svgs
) VALUES (
  'rrb_ntpc_graduate_pyq_master', 2985, 13, 'reason_ch13', 'General Intelligence and Reasoning', 'Miscellaneous Verbal', 'Graduate',
  'Each of seven people, E, F, G, H, J, K and L, has an exam on a different day of a week, starting from Monday and ending on Sunday of the same week. Only three people have exams between L and J. Only three people have exams between H and K. E has exam on some day before J and on some day after F. Only G has exam before K. How many people have exams before L?', NULL, '{"a": "Three", "b": "One", "c": "Four", "d": "Two"}'::jsonb, NULL, 'd', 'Step-by-step deduction:
1. 7 people: E, F, G, H, J, K, L with exams from Monday(1) to Sunday(7).
2. ''Only G has exam before K'' -> Monday = G, Tuesday = K.
3. ''Only three people have exams between H and K'' -> Tuesday(2) + 4 = Saturday(6) = H.
4. ''Only three people have exams between L and J'' -> L and J are on Wednesday(3) and Sunday(7).
5. ''E has exam on some day before J and on some day after F'' -> F < E < J. Thus J must be Sunday(7), meaning Wednesday = L! Then Thursday = F, Friday = E.
6. Schedule: Mon = G, Tue = K, Wed = L, Thu = F, Fri = E, Sat = H, Sun = J.
7. Number of people with exams before L (Wednesday) = Monday and Tuesday = 2 people (G and K).
Hence, the correct option is D (Two).', NULL,
  NULL, NULL, NULL
)
