INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH13_Q0024', 3005, 'General Intelligence and Reasoning', 'reason_ch13', 13, 'Miscellaneous Verbal', 24,
  'Number Operations & Digit Rearrangement', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '16/03/2026', '12:45 PM - 2:15 PM', 'Graduate',
  'If 3 is added to each even digit and 2 is subtracted from each odd digit in the number 5723946, how many digits will appear more than once in the new number thus formed?', NULL, '{"a": "None", "b": "Two", "c": "One", "d": "Three"}'::jsonb, NULL, 'b',
  'Step-by-step deduction:
Original number: 5 7 2 3 9 4 6
Rule: Add 3 to each even digit, subtract 2 from each odd digit.
- 5 (odd) -> 5 - 2 = 3
- 7 (odd) -> 7 - 2 = 5
- 2 (even) -> 2 + 3 = 5
- 3 (odd) -> 3 - 2 = 1
- 9 (odd) -> 9 - 2 = 7
- 4 (even) -> 4 + 3 = 7
- 6 (even) -> 6 + 3 = 9
New number: 3 5 5 1 7 7 9
Digits appearing more than once: 5 (appears twice) and 7 (appears twice).
Total digits appearing more than once = 2.
Hence, the correct option is B (Two).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
