INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH13_Q0029', 3010, 'General Intelligence and Reasoning', 'reason_ch13', 13, 'Miscellaneous Verbal', 29,
  'Number Operations & Digit Rearrangement', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '27/03/2026', '9:00 AM - 10:30 AM', 'Graduate',
  'If 1 is added to each odd digit and 2 is subtracted from each even digit in the number 6587134, which of the following digits will be second from the left end in the new number thus formed?', NULL, '{"a": "4", "b": "8", "c": "6", "d": "5"}'::jsonb, NULL, 'c',
  'Step-by-step deduction:
Original number: 6 5 8 7 1 3 4
Rule: Add 1 to each odd digit, subtract 2 from each even digit.
- 1st digit: 6 (even) -> 6 - 2 = 4
- 2nd digit: 5 (odd) -> 5 + 1 = 6
- 3rd digit: 8 (even) -> 8 - 2 = 6
- 4th digit: 7 (odd) -> 7 + 1 = 8
- 5th digit: 1 (odd) -> 1 + 1 = 2
- 6th digit: 3 (odd) -> 3 + 1 = 4
- 7th digit: 4 (even) -> 4 - 2 = 2
New number: 4 6 6 8 2 4 2
The second digit from the left end is 6.
Hence, the correct option is C (6).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
