INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH13_Q0058', 3039, 'General Intelligence and Reasoning', 'reason_ch13', 13, 'Miscellaneous Verbal', 58,
  'Number Operations & Digit Rearrangement', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '19/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'If 1 is added to each odd digit and 2 is subtracted from each even digit in the number 5714623, what will be the sum of the digits that are second from the left and second from the right?', NULL, '{"a": "8", "b": "7", "c": "6", "d": "9"}'::jsonb, NULL, 'a',
  'Step-by-step deduction:
Original number: 5 7 1 4 6 2 3
Rule: Add 1 to each odd digit, subtract 2 from each even digit.
- 1st digit: 5 (odd) -> 5 + 1 = 6
- 2nd digit: 7 (odd) -> 7 + 1 = 8
- 3rd digit: 1 (odd) -> 1 + 1 = 2
- 4th digit: 4 (even) -> 4 - 2 = 2
- 5th digit: 6 (even) -> 6 - 2 = 4
- 6th digit: 2 (even) -> 2 - 2 = 0
- 7th digit: 3 (odd) -> 3 + 1 = 4
New number: 6 8 2 2 4 0 4
Second digit from the left = 8.
Second digit from the right = 0.
Sum = 8 + 0 = 8.
Hence, the correct option is A (8).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
