INSERT INTO public.rrb_ntpc_graduate_pyqs (
  id, master_id, subject, chapter_id, chapter_num, chapter_name, chapter_q_num,
  subtopic, exam_name, exam_tag, exam_stage, exam_date, exam_shift, target_level,
  question_text, question_text_hi, options, options_hi, correct_option,
  solution_text, solution_text_hi, has_image, image_type, svg_content, option_svgs, solution_svg, verification_status
) VALUES (
  'RRB_NTPC_REASON_CH13_Q0084', 3065, 'General Intelligence and Reasoning', 'reason_ch13', 13, 'Miscellaneous Verbal', 84,
  'Number Operations & Digit Rearrangement', 'RRB NTPC', 'RRB NTPC Graduate Level', 'Stage-I / Stage-II', '22/03/2026', '4:30 PM - 6:00 PM', 'Graduate',
  'If 1 is added to each odd digit and 2 is subtracted from each even digit in the number 8634157, which of the following digits will be second from the left?', NULL, '{"a": "1", "b": "3", "c": "4", "d": "2"}'::jsonb, NULL, 'c',
  'Step-by-step deduction:
Original number: 8 6 3 4 1 5 7
Rule: Add 1 to each odd digit, subtract 2 from each even digit.
- 1st digit: 8 (even) -> 8 - 2 = 6
- 2nd digit: 6 (even) -> 6 - 2 = 4
- 3rd digit: 3 (odd) -> 3 + 1 = 4
- 4th digit: 4 (even) -> 4 - 2 = 2
- 5th digit: 1 (odd) -> 1 + 1 = 2
- 6th digit: 5 (odd) -> 5 + 1 = 6
- 7th digit: 7 (odd) -> 7 + 1 = 8
New number: 6 4 4 2 2 6 8
Second digit from the left = 4.
Hence, the correct option is C (4).', NULL, false, NULL, NULL, NULL, NULL, 'verified'
)
