    <polygon points="10,35 50,55 50,105 10,85" fill="#e0f2fe" stroke="#0369a1" stroke-width="1.5"/>
    <polygon points="50,55 90,35 90,85 50,105" fill="#dcfce7" stroke="#15803d" stroke-width="1.5"/>
